import { AsyncDuckDB } from '../../duckdb-wasm';
import { MotherDuckLogLevel } from './MotherDuckLogLevel.js';
export interface LoadMotherDuckWasmExtensionOptions {
    /**
     * DuckDB instance.
     */
    instance: AsyncDuckDB;
    /**
     * MotherDuck authentication token.
     */
    token: string;
    /**
     * URL prefix of a custom extension repository where the MotherDuck Wasm client extension can be found.
     *
     * Note that this should not contain either the extension version or the `/duckdb-wasm` suffix.
     *
     * Defaults to https://app.motherduck.com.
     */
    extensionRepositoryUrlPrefix?: URL;
    /**
     * Version of the MotherDuck Wasm client extension, in the form `{branch}@{SHA}`.
     *
     * If not given, the latest version will be fetched from `{extensionRepositoryUrlPrefix}/version`.
     */
    extensionVersion?: string;
    /**
     * MotherDuck API URL.
     *
     * Defaults to https://api.motherduck.com.
     */
    apiUrl?: URL;
    /**
     * MotherDuck log level.
     *
     * Defaults to MotherDuckLogLevel.INFO.
     */
    logLevel?: MotherDuckLogLevel;
    /**
     * Skip the "welcome pack", the first message exchange between the MotherDuck client and server.
     */
    skipWelcomePack?: boolean;
}
